SELECT cluster_id,
  NULLIF(COUNT(DISTINCT CASE WHEN identity_scope='PERSON' THEN CONCAT(fingerprint_key_id,':',HEX(fingerprint)) END),0) user_count,
  COUNT(DISTINCT CASE WHEN identity_type='DEVICE_SN' THEN CONCAT(fingerprint_key_id,':',HEX(fingerprint)) END) device_count
FROM t_phase_one_feedback_cluster_identity_projection
WHERE generation_id=#{generationId} AND cluster_id IN
#{value}
  AND source_channel IN
#{value}

  AND UPPER(COALESCE(NULLIF(function_module,''),'UNKNOWN')) IN
  #{value}


  AND (UPPER(province_code) IN
  #{value}
  OR UPPER(city_code) IN
  #{value})

AND reported_at>=#{criteria.startTime}
AND reported_at<=#{criteria.endTime}
GROUP BY cluster_id
